package helium314.keyboard.latin.ai.dictation;
import java.io.*;import java.nio.file.*;import org.junit.Test;import static org.junit.Assert.*;
public class RamblrCoreTest {
 private Class<?> type(String name){try{return Class.forName("helium314.keyboard.latin.ai.dictation.ramblr."+name);}catch(Exception e){throw new AssertionError("Ramblr core not integrated",e);}}
 @Test public void recordingTransitionsHaveSingleOwner() throws Exception {Class<?> c=type("RecordingStateMachine");Object state=c.getConstructor().newInstance();assertEquals(true,c.getMethod("tryStartRecording").invoke(state));assertEquals(false,c.getMethod("tryStartRecording").invoke(state));assertEquals(true,c.getMethod("tryStartTranscribing").invoke(state));assertEquals(false,c.getMethod("tryStartTranscribing").invoke(state));c.getMethod("reset").invoke(state);assertEquals(true,c.getMethod("tryStartRecording").invoke(state));}
 @Test public void wavHeaderHasCorrectPcmContainer() throws Exception {Class<?> c=type("WavWriter");byte[] header=(byte[])c.getMethod("header",long.class,int.class,int.class,int.class).invoke(c.getField("INSTANCE").get(null),32000L,16000,1,16);assertEquals(44,header.length);assertEquals("RIFF",new String(header,0,4,java.nio.charset.StandardCharsets.US_ASCII));assertEquals("WAVE",new String(header,8,4,java.nio.charset.StandardCharsets.US_ASCII));assertEquals(32000,java.nio.ByteBuffer.wrap(header,40,4).order(java.nio.ByteOrder.LITTLE_ENDIAN).getInt());}
 @Test public void durationUsesMonotonicElapsedBudget() throws Exception {Class<?> c=type("RecordingDurationCap");Object o=c.getField("INSTANCE").get(null);assertEquals(false,c.getMethod("exceeded",long.class,long.class,long.class).invoke(o,1000L,120999L,120000L));assertEquals(true,c.getMethod("exceeded",long.class,long.class,long.class).invoke(o,1000L,121000L,120000L));}
 @Test public void supersededReaderCannotStealNewRecording() throws Exception {Class<?> stateType=type("RecordingStateMachine"),handoff=type("RecorderHandoff");Object state=stateType.getConstructor().newInstance(),owner=handoff.getField("INSTANCE").get(null);assertEquals(true,stateType.getMethod("tryStartRecording").invoke(state));assertEquals(false,handoff.getMethod("shouldClaimTranscribing",boolean.class).invoke(owner,true));Object current=stateType.getMethod("current").invoke(state);assertEquals(true,handoff.getMethod("discarded",boolean.class,current.getClass()).invoke(owner,true,current));}
 private void assertPcmWrite(int cap,byte[] input,int expected) throws Exception {Path root=Files.createTempDirectory("pcm-cap");File pcm=root.resolve("take.pcm").toFile();Class<?> c=type("PcmFileBuffer");Object buffer=c.getConstructor(File.class,long.class).newInstance(pcm,(long)cap);try{assertEquals(false,c.getMethod("write",byte[].class,int.class,int.class).invoke(buffer,input,0,input.length));assertEquals((long)expected,c.getMethod("getBytesWritten").invoke(buffer));}finally{c.getMethod("close").invoke(buffer);}assertEquals(expected,pcm.length());pcm.delete();root.toFile().delete();}
 @Test public void pcmBufferNeverWritesHalfASixteenBitSample() throws Exception {assertPcmWrite(6,new byte[]{1,2,3,4,5},4);}
 @Test public void pcmBufferWritesOnlyUpToEvenHardCap() throws Exception {assertPcmWrite(6,new byte[]{1,2,3,4,5,6,7,8},6);}
}
